from pathlib import Path
from html import escape

ROOT = Path(__file__).resolve().parents[1] / 'site'
repo = 'https://github.com/OpenXeroth/acoustic-re-id-research'

def page(path, title, description, body, active='', script=False, extra_script=''):
    links = [('/naturecam/', 'NatureCam'), ('/acoustic-re-id-research/', 'Research'), ('/djuma-birds/', 'Djuma birds')]
    nav = ''.join(f'<a href="{u}"'+(' aria-current="page"' if n == active else '')+f'>{n}</a>' for u,n in links)
    content = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} · OpenXeroth</title><meta name="description" content="{escape(description)}"><meta name="theme-color" content="#738878"><link rel="icon" href="/assets/xeroth-green.png"><link rel="canonical" href="https://open.xeroth.ai{path}"><meta property="og:title" content="{escape(title)} · OpenXeroth"><meta property="og:description" content="{escape(description)}"><link rel="stylesheet" href="/assets/site.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="top"><div class="wrap"><div class="nav"><a class="brand" href="/" aria-label="OpenXeroth home"><img src="/assets/xeroth-green.png" alt="" width="40" height="40">Open<span>Xeroth</span></a><nav aria-label="Main navigation">{nav}<a class="nav-github" href="https://github.com/OpenXeroth">GitHub ↗</a></nav></div></div></header><main id="main" class="wrap">{body}</main><footer><div class="wrap footer-row"><div><a class="brand" href="/">Open<span>Xeroth</span></a><p>Open tools for understanding wildlife.</p><span>OpenXeroth is part of <a href="https://xeroth.ai">Xeroth</a>.</span></div><div class="footer-links"><a href="https://www.youtube.com/@djumacam">Djuma Cam on YouTube ↗</a><a href="https://github.com/OpenXeroth">GitHub ↗</a><a href="https://www.djuma.com/djumacam">The Djuma story ↗</a></div></div></footer>{'<script type="module" src="/assets/birds.js"></script>' if script else ''}{extra_script}</body></html>'''
    p = ROOT / path.strip('/') / 'index.html';p.parent.mkdir(parents=True, exist_ok=True);p.write_text(content)

